local function shallowEqual(p1, p2) -- line: 8
    if p1 == p2 then
        return true
    end

    if type(p1) ~= "table" or type(p2) ~= "table" then
        return false
    end

    for v1, v2 in p1 do
        if p2[v1] ~= v2 then
            return false
        end
    end

    for v3, v4 in p2 do
        if p1[v3] ~= v4 then
            return false
        end
    end

    return true
end

return shallowEqual
